action.command:
cat > /tmp/drift.php <<'EOF'
<?php
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$sync = $storage->listAll();
$active = \Drupal::configFactory()->listAll();
$onlySync = array_diff($sync,$active);
$onlyActive = array_diff($active,$sync);
$diff = 0; $same=0;
$syncStorage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
foreach (array_intersect($sync,$active) as $n) {
  $a = \Drupal::config($n)->getRawData();
  $s = $syncStorage->read($n);
  unset($a['uuid'], $a['_core'], $s['uuid'], $s['_core']);
  if ($a != $s) $diff++; else $same++;
}
echo "sync total: " . count($sync) . PHP_EOL;
echo "active total: " . count($active) . PHP_EOL;
echo "only in sync: " . count($onlySync) . PHP_EOL;
echo "only in db: " . count($onlyActive) . PHP_EOL;
echo "different (ignoring uuid/_core): $diff" . PHP_EOL;
echo "same: $same" . PHP_EOL;
EOF
cd /workspace && cp /tmp/drift.php /workspace/drift_tmp.php && su ddevuser -c "ddev drush php:script drift_tmp.php" 2>&1 | tail -8; rm -f /workspace/drift_tmp.php

